"""Homogeneous linear differential equations with constant coefficient."""
def make_unit(page,ex,summary):
 return ('Óhliðraðar deildajöfnur',[
 page('Þegar breytingahraðinn ræðst af fallgildinu','Tengja jöfnuna y′ = ky við afleiður vísisfalla.',r'''<p>Í einingu 9 var afleiðan oft gefin beint sem fall af x, til dæmis y′=2x. Nú skoðum við jöfnur þar sem <strong>fallið sjálft kemur fyrir hægra megin</strong>:</p>\[y'=2y.\]<p>Afleiðan á að vera tvöfalt fallgildið við hvert x. Við getum því ekki heildað hægri hliðina eins og y væri fasti.</p><h2>Vísisfall sem lausn</h2><p>Rifjum upp diffrun vísisfalls:</p>\[\frac{d}{dx}e^{kx}=ke^{kx}.\]<p>Afleiðan er fasti sinnum fallið sjálft. Það er einmitt mynstrið sem við leitum að.</p><h3>Sýnidæmi 10.1.1</h3><p>Fallið y=3e²ˣ hefur afleiðuna:</p>\[y'=6e^{2x}=2y.\]<p>Það uppfyllir því y′=2y. Stuðullinn 3 er ekki nauðsynlegur: fyrir hvaða fasta C sem er gefur y=Ce²ˣ afleiðuna 2Ce²ˣ.</p><h2>Tvær framsetningar sömu jöfnu</h2>\[y'=2y.\]\[y'-2y=0.\]<p>Við getum fært liðinn með y yfir vinstra megin. Í þessari einingu skrifum við jöfnurnar yfirleitt á forminu:</p>\[y'+ay=0.\]<p>Hér er a fasti. Þetta er <strong>óhliðruð línuleg deildajafna af fyrsta stigi</strong>. Hún er af fyrsta stigi því hæsta afleiðan er y′. Hún er línuleg því y og y′ koma fyrir í fyrsta veldi og eru ekki margfölduð saman. Orðið óhliðruð vísar hér til þess að hægri hliðin er núll.</p>''',[
 ex(r'Athugaðu hvort \(y=4e^{3x}\) uppfylli \(y\prime=3y\).','Diffraðu fallið og berðu saman við 3y.',r'\(y\prime=12e^{3x}\).',r'Já. Bæði y′ og 3y eru \(12e^{3x}\).','#s1'),
 ex(r'Skrifaðu \(y\prime=-5y\) á forminu \(y\prime+ay=0\). Hvert er a?','Færðu liðinn hægra megin yfir jafnaðarmerkið.','Bættu 5y við báðar hliðar.',r'\(y\prime+5y=0\), svo a=5.','#s1'),
 ex(r'Skrifaðu \(y\prime=4y\) á forminu \(y\prime+ay=0\). Hvert er a?','Færðu 4y yfir vinstra megin.','Formerkið breytist við umritunina.',r'\(y\prime-4y=0\), svo a=−4.','#s1')]),
 page('Almenna lausnin','Nota lausnarformið y = Ce⁻ᵃˣ og athuga það með diffrun.',r'''<p>Fyrir jöfnuna</p>\[y'+ay=0\]<p>þar sem a er fasti er almenna lausnin:</p><div class="formula">\[y=Ce^{-ax}.\]</div><p>Fastinn C má vera hvaða rauntala sem er, líka núll.</p><h2>Hvers vegna er mínus í veldinu?</h2><p>Jafnan segir y′=−ay. Afleiða eᵏˣ er keᵏˣ, svo stuðullinn í veldinu þarf að vera −a. Athugum lausnarformið:</p>\[y'=-aCe^{-ax}.\]\[y'+ay=-aCe^{-ax}+aCe^{-ax}=0.\]<p>Þetta gildir fyrir öll x og öll C.</p><h3>Sýnidæmi 10.2.1 — jákvæður stuðull a</h3>\[y'+3y=0.\]<p>Hér er a=3. Því er:</p>\[y=Ce^{-3x}.\]<h3>Sýnidæmi 10.2.2 — neikvæður stuðull a</h3>\[y'-2y=0.\]<p>Hér er a=−2, svo −a=2:</p>\[y=Ce^{2x}.\]<h2>Ef stuðull er fyrir framan y′</h2><h3>Sýnidæmi 10.2.3</h3>\[2y'+6y=0.\]<p>Deilum fyrst með 2 til að fá stuðulinn 1 við y′:</p>\[y'+3y=0.\]\[y=Ce^{-3x}.\]<aside>Lesið formerkið með stuðlinum. Í y′−2y=0 er a=−2. Ef a=0 fæst y′=0 og lausnin er fastafallið y=C.</aside>''',[
 ex(r'Finndu almenna lausn \(y\prime+4y=0\).','Lestu a úr jöfnunni.','Hér er a=4, svo veldið er −4x.',r'\(y=Ce^{-4x}\). Þá er y′=−4Ce⁻⁴ˣ og y′+4y=0.','#s2'),
 ex(r'Finndu almenna lausn \(y\prime-3y=0\).','Taktu mínusmerkið með þegar þú ákveður a.','Hér er a=−3.',r'\(y=Ce^{3x}\). Þá er y′=3Ce³ˣ og y′−3y=0.','#s2'),
 ex(r'Finndu almenna lausn \(3y\prime+2y=0\).','Deildu fyrst með 3.','Jafnan verður y′+(2/3)y=0.',r'\(y=Ce^{-2x/3}\). Þá er \(3y\prime=-2Ce^{-2x/3}\) og \(2y=2Ce^{-2x/3}\), svo summan er núll.','#s2'),
 ex(r'Er núllfallið \(y=0\) lausn \(y\prime+7y=0\)?','Settu fallið og afleiðu þess inn í jöfnuna.','Afleiða núllfallsins er núll.',r'Já. Vinstri hliðin verður 0+7·0=0. Þetta er lausnin sem fæst þegar C=0.','#s2')]),
 page('Upphafsskilyrði','Ákvarða fastann og sannreyna tiltekna lausn.',r'''<p>Eins og áður velur upphafsskilyrði eina lausn úr fjölskyldunni. Þegar skilyrðið er gefið við x=0 er sérstaklega einfalt að finna C, því e⁰=1:</p>\[y(0)=Ce^0=C.\]<h3>Sýnidæmi 10.3.1 — skilyrði við x=0</h3>\[y'+2y=0.\]\[y(0)=5.\]<p>Almenna lausnin og skilyrðið gefa:</p>\[y=Ce^{-2x}.\]\[5=Ce^0=C.\]<p>Tiltekna lausnin er því:</p>\[y=5e^{-2x}.\]<p>Athugum báðar kröfurnar:</p>\[y'+2y=-10e^{-2x}+10e^{-2x}=0.\]\[y(0)=5.\]<h2>Upphafspunkturinn þarf ekki að vera núll</h2><h3>Sýnidæmi 10.3.2</h3>\[y'-y=0.\]\[y(1)=2.\]<p>Almenna lausnin er y=Ceˣ. Setjum x=1 og y=2 inn:</p>\[2=Ce.\]\[C=2e^{-1}.\]<p>Því fæst:</p>\[y=2e^{x-1}.\]<p>Afleiðan er y′=2eˣ⁻¹=y og y(1)=2. Bæði jafnan og skilyrðið eru uppfyllt.</p><aside>C jafngildir y(0) í forminu y=Ce⁻ᵃˣ. Það er ekki sjálfkrafa jafnt gefna fallgildinu þegar upphafsskilyrðið er við annað x-gildi.</aside>''',[
 ex(r'Leystu \(y\prime+3y=0\) með \(y(0)=4\).','Finndu fyrst almenna lausn.','Við x=0 er e⁰=1.',r'\(y=4e^{-3x}\). Þá er y′+3y=0 og y(0)=4.','#s3'),
 ex(r'Leystu \(y\prime-2y=0\) með \(y(0)=-3\).','Upphafsgildið má vera neikvætt.','Almenna lausnin er y=Ce²ˣ.',r'\(y=-3e^{2x}\). Þá er y′=−6e²ˣ=2y og y(0)=−3.','#s3'),
 ex(r'Leystu \(y\prime+y=0\) með \(y(2)=3\).','Settu upphafsskilyrðið inn í y=Ce⁻ˣ.',r'\(3=Ce^{-2}\), svo \(C=3e^2\).',r'\(y=3e^{2-x}\). Afleiðan er −y og y(2)=3.','#s3')]),
 page('Lausnarferlar, vöxtur og hnignun','Túlka áhrif stuðulsins a og upphafsgildisins á lausnina.',r'''<p>Í lausninni y=Ce⁻ᵃˣ ráða a og C ólíkum þáttum. Fastinn C er upphafsgildið y(0). Stuðullinn a ræður því hvernig lausnin breytist með x.</p><h2>Þegar upphafsgildið er jákvætt</h2><ul><li><strong>a&gt;0:</strong> y′=−ay er neikvætt. Lausnin minnkar og stefnir á núll þegar x vex.</li><li><strong>a&lt;0:</strong> y′=−ay er jákvætt. Lausnin vex.</li><li><strong>a=0:</strong> afleiðan er núll. Lausnin er föst.</li></ul><h2>Breyttu stuðlinum og upphafsgildinu</h2><p>Grafið sýnir lausnina y=Ce⁻ᵃˣ. Skoðaðu einnig hvað gerist þegar C er núll eða neikvætt.</p><div class="formula" id="exp-family"><svg viewBox="0 0 420 500" style="max-width:420px;display:block;margin:16px auto" role="img" aria-label="Lausnarferill óhliðraðrar deildajöfnu" id="exp-graph"></svg><label for="exp-a"><strong>Stuðull a: <output id="exp-a-value">1</output></strong></label><input id="exp-a" type="range" min="-1" max="1" step="0.25" value="1" style="display:block;width:100%;margin:18px 0;accent-color:var(--accent)"><label for="exp-c"><strong>Upphafsgildi C = y(0): <output id="exp-c-value">2</output></strong></label><input id="exp-c" type="range" min="-3" max="3" step="0.5" value="2" style="display:block;width:100%;margin:18px 0;accent-color:var(--accent)"><p id="exp-equation"></p><p id="exp-behaviour" role="status"></p></div><h2>Þegar upphafsgildið er neikvætt</h2><p>Vísisþátturinn e⁻ᵃˣ er alltaf jákvæður. Formerki lausnarinnar er því alltaf það sama og formerki C.</p><p>Ef a&gt;0 og C&lt;0 nálgast ferillinn núll <strong>neðan frá</strong>: fallgildið hækkar, þótt algildið |y| minnki. Ef a&lt;0 og C&lt;0 verða fallgildin sífellt neikvæðari þegar x vex.</p><p>Núllfallið er <strong>jafnvægislausn</strong>: þegar C=0 er lausnin alltaf y=0. Fyrir a≠0 er það eina fastalausnin; ef a=0 er sérhvert fastafall lausn.</p>''',[
 ex(r'Lausnin er \(y=6e^{-2x}\). Vex hún eða minnkar þegar x vex? Hverju stefnir hún á?','Skoðaðu formerki veldisins og upphafsgildið.','e⁻²ˣ minnkar í átt að núlli.',r'Hún minnkar og stefnir á núll. Hún er þó jákvæð fyrir öll x.','#s4'),
 ex(r'Lausnin er \(y=-2e^{-x}\). Hækkar fallgildið eða lækkar þegar x vex?','Athugaðu formerki afleiðunnar.',r'\(y\prime=2e^{-x}>0\).',r'Fallgildið hækkar og stefnir á núll neðan frá. Algildið |y| minnkar.','#s4'),
 ex(r'Hvor lausnin nálgast núll hraðar fyrir x>0: \(y_1=5e^{-x}\) eða \(y_2=5e^{-3x}\)?','Báðar byrja í 5. Berðu saman veldisvísana þegar x>0.','e⁻³ˣ er minna en e⁻ˣ þegar x>0.',r'y₂ nálgast núll hraðar. Hún hefur stærri jákvæðan stuðul a og er minni en y₁ fyrir öll x>0.','#s4')]),
 page('Hagnýting: breyting í hlutfalli við magn','Setja upp einfalt líkan, leysa það og túlka niðurstöðu.',r'''<p>Jafna á forminu y′=ky kemur fram þegar breytingahraði er í beinu hlutfalli við það magn sem er til staðar. Breytan er oft tíminn t og óþekkta fallið táknað með M eða N.</p><h3>Sýnidæmi 10.5.1 — magn minnkar</h3><p>Í einföldu líkani brotnar efni niður þannig að breytingahraði massans er −0,2 sinnum massinn. M(t) er massi í grömmum og t tími í klukkustundum. Upphafsmassinn er 200 g.</p>\[M'(t)=-0{,}2M(t).\]\[M(0)=200.\]<p>Umritum á formið sem við þekkjum:</p>\[M'(t)+0{,}2M(t)=0.\]<p>Almenna lausnin er \(M(t)=Ce^{-0{,}2t}\). Upphafsskilyrðið gefur C=200:</p>\[M(t)=200e^{-0{,}2t}.\]<p>Eftir 5 klukkustundir er massinn:</p>\[M(5)=200e^{-1}\approx73{,}6\text{ g}.\]<p>Athugun: \(M\prime(t)=-40e^{-0{,}2t}=-0{,}2M(t)\) og M(0)=200. Stuðullinn 0,2 er mældur í h⁻¹, svo afleiðan hefur eininguna g/h.</p><h2>Hvenær er helmingurinn eftir?</h2><p><strong>Helmingunartími</strong> er sá tími sem það tekur magnið að helmingast. Hér leysum við M(t)=100:</p>\[200e^{-0{,}2t}=100.\]\[e^{-0{,}2t}=\frac12.\]\[-0{,}2t=\ln\!\left(\frac12\right)=-\ln2.\]\[t=\frac{\ln2}{0{,}2}\approx3{,}47\text{ klst.}\]<p>Sami tími líður frá 100 g niður í 50 g samkvæmt líkaninu. Jafnan lýsir samfelldri breytingu; stuðullinn 0,2 merkir ekki að nákvæmlega 20% hverfi á hverri heilli klukkustund.</p><h2>Jákvæður breytingahraði</h2><p>Ef magn vex í stað þess að minnka er fastinn við magnið í y′=ky jákvæður. Til dæmis gefa N′=0,3N og N(0)=100 lausnina:</p>\[N(t)=100e^{0{,}3t}.\]<p>Á forminu N′+aN=0 er þá a=−0,3. Taktu eftir formerkjunum þegar líkanið er tengt við lausnarregluna.</p>''',[
 ex(r'Magn uppfyllir \(M\prime=-0{,}5M\) og \(M(0)=80\). Finndu M(t) og magnið eftir 2 tímaeiningar.','Upphafsgildið ákvarðar stuðulinn fyrir framan vísisfallið.',r'\(M(t)=80e^{-0{,}5t}\).',r'\(M(t)=80e^{-0{,}5t}\) og \(M(2)=80e^{-1}\approx29{,}4\) magneiningar. Afleiðan er −0,5M og M(0)=80.','#s5'),
 ex(r'Magn vex samkvæmt \(N\prime=0{,}2N\) og \(N(0)=50\). Finndu N(t).','Skrifaðu jöfnuna sem N′−0,2N=0.','Hér er a=−0,2.',r'\(N(t)=50e^{0{,}2t}\). Afleiðan er 0,2N og N(0)=50.','#s5'),
 ex(r'Finndu helmingunartíma fyrir \(M(t)=80e^{-0{,}5t}\).','Settu M(t)=40 og einangraðu vísisfallið.',r'Eftir deilingu með 80 fæst \(e^{-0{,}5t}=1/2\). Taktu náttúrulegan logra.',r'\(t=\ln2/0{,}5\approx1{,}39\) tímaeiningar.','#s5')]),
 page('Samantekt, orðalisti og formúlur','Tengja jöfnu, lausnarform, upphafsgildi og hegðun lausnar.',summary([
 'Jafnan y′+ay=0 er óhliðruð línuleg deildajafna af fyrsta stigi, þar sem a er fasti.','Almenna lausnin er y=Ce⁻ᵃˣ og inniheldur líka núlllausnina.','Ef stuðullinn við y′ er ekki 1 er fyrst deilt með honum.','Upphafsskilyrði ákvarðar C. Í þessu lausnarformi er C=y(0).','Fyrir a>0 stefnir sérhver lausn á núll þegar x stefnir á óendanlegt.','Athuga þarf bæði deildajöfnuna og upphafsskilyrðið með tilteknu lausninni.'
 ],[
 ('<a href="#s1">Óhliðruð línuleg deildajafna</a> <span lang="en">(homogeneous linear differential equation)</span>','Hér: jafna á forminu y′+ay=0, þar sem a er fasti.'),
 ('<a href="#s1">Fyrsta stigs deildajafna</a> <span lang="en">(first-order differential equation)</span>','Deildajafna þar sem hæsta afleiðan sem kemur fyrir er fyrsta afleiða.'),
 ('<a href="#s2">Almenn lausn</a> <span lang="en">(general solution)</span>','Lausnafjölskyldan y=Ce⁻ᵃˣ fyrir allar rauntölur C.'),
 ('<a href="#s3">Upphafsgildi</a> <span lang="en">(initial value)</span>','Gefið fallgildi í tilteknum upphafspunkti.'),
 ('<a href="#s4">Jafnvægislausn</a> <span lang="en">(equilibrium solution)</span>','Lausn sem er föst og hefur því afleiðuna núll.'),
 ('<a href="#s5">Helmingunartími</a> <span lang="en">(half-life)</span>','Tíminn sem það tekur magn að helmingast samkvæmt hnignunarlíkani.')
 ],r'''<p><strong>Lausn óhliðraðrar línulegrar deildajöfnu með föstum stuðli</strong></p>\[y'+ay=0.\]\[y=Ce^{-ax}.\]<p>Hér er a fasti og C frjáls rauntala.</p><p><strong>Lausn með upphafsskilyrði við x₀</strong></p>\[y(x_0)=y_0.\]\[y=y_0e^{-a(x-x_0)}.\]<p>Þetta er sama lausnarform og að ofan; \(C=y_0e^{ax_0}\). Við x₀=0 einfaldast það í y=y₀e⁻ᵃˣ.</p><p><strong>Samfelldur veldisvöxtur eða hnignun</strong></p>\[M'=kM.\]\[M(t)=M_0e^{kt}.\]<p>Hér er M(0)=M₀ og k=−a. Fyrir M₀>0 gefur k>0 vöxt en k&lt;0 hnignun.</p><p><strong>Helmingunartími við veldishnignun</strong></p>\[T_{1/2}=\frac{\ln2}{a}.\]<p>Hér er M(t)=M₀e⁻ᵃᵗ, a>0 og M₀>0. Eining a er andhverfa tímaeiningarinnar.</p>''')+r'''<h2>Algeng mistök</h2><ul><li>Að missa mínusmerkið í veldinu −ax.</li><li>Að nota stuðulinn við y áður en stuðull y′ hefur verið gerður að 1.</li><li>Að sleppa núlllausninni.</li><li>Að setja C jafnt gefnu fallgildi þótt skilyrðið sé ekki við x=0.</li><li>Að segja að fallið minnki að núlli þegar það nálgast núll neðan frá.</li></ul><h2>Athugaðu skilninginn</h2><ul><li>Geturðu athugað almenna lausnarformið með diffrun?</li><li>Geturðu fundið a þegar jafnan er gefin sem y′=ky?</li><li>Geturðu tengt formerki a og C við hegðun lausnarinnar?</li></ul>'''),
 page('Blandað dæmasafn','Velja lausnaleið, rökstyðja og sannreyna niðurstöðu.','',[
 ex(r'Leystu \(y\prime+5y=0\), með \(y(0)=2\).','Ákvarðaðu fyrst a og finndu síðan C.','Almenna lausnin er y=Ce⁻⁵ˣ.',r'\(y=2e^{-5x}\). Þá er y′+5y=0 og y(0)=2.','#s3'),
 ex(r'Leystu \(2y\prime-6y=0\), með \(y(0)=1\).','Gerðu stuðulinn við y′ að 1 áður en þú notar lausnarformið.','Jafnan verður y′−3y=0.',r'\(y=e^{3x}\). Þá er 2y′−6y=6e³ˣ−6e³ˣ=0 og y(0)=1.','#s2'),
 ex(r'Leystu \(y\prime+2y=0\), með \(y(1)=4\).','Upphafsskilyrðið er við x=1, ekki x=0.',r'\(4=Ce^{-2}\), svo \(C=4e^2\).',r'\(y=4e^{-2(x-1)}\). Afleiðan er −2y og y(1)=4.','#s3'),
 ex(r'Nemandi fær \(y=3e^{2x}\) fyrir \(y\prime+2y=0\), með \(y(0)=3\). Hvað er rétt og hvað þarf að laga?','Athugaðu skilyrðið og jöfnuna sitt í hvoru lagi.','Upphafsskilyrðið stenst, en reiknaðu y′+2y.',r'Upphafsskilyrðið stenst. En y′+2y=12e²ˣ, sem er ekki núll. Rétta lausnin er \(y=3e^{-2x}\).','#s2'),
 ex(r'Lausnin er \(y=-4e^{-3x}\). Finndu deildajöfnu á forminu y′+ay=0 og lýstu hegðun lausnarinnar þegar x vex.','Finndu sambandið milli afleiðunnar og fallsins.','Afleiðan er 12e⁻³ˣ=−3y.',r'Jafnan er \(y\prime+3y=0\). Fallgildið hækkar og stefnir á núll neðan frá; það er alltaf neikvætt.','#s4'),
 ex(r'Magn M minnkar með breytingahraða sem er −0,1 sinnum magnið. Upphafsmagnið er 120 einingar. Settu upp deildajöfnu og finndu hvenær 30 einingar eru eftir.','Finndu fyrst M(t). Settu svo M(t)=30.',r'\(M(t)=120e^{-0{,}1t}\), svo \(e^{-0{,}1t}=1/4\).',r'\(M\prime=-0{,}1M\), með M(0)=120. Tíminn er \(t=\ln4/0{,}1\approx13{,}86\) tímaeiningar.','#s5'),
 ex(r'Finndu allar fastalausnir \(y\prime-2y=0\).','Fyrir fastafall y=b er y′=0.','Settu þetta inn í upphaflegu jöfnuna.','Jafnan verður −2b=0. Því er y=0 eina fastalausnin.','#s4'),
 ex(r'Leystu \(y\prime=4x\), með \(y(0)=3\). Hvers vegna á formið y=Ce⁻ᵃˣ ekki við hér?','Skoðaðu hvort hægri hliðin sé fasti sinnum y eða gefið fall af x.','Hér nægir að finna stofnfall 4x og nota skilyrðið.',r'\(y=2x^2+3\). Afleiðan er 4x og y(0)=3. Jafnan er y′=f(x), en ekki y′+ay=0 með föstum a.','unit-9.html#s4')])])
